def transform(grid):
    # Infer an exact-cover tiling of the occupied cells by 2x2 squares and
    # three-cell L trominoes.  Prefer squares; orient L colors by missing corner.
    h, w = len(grid), len(grid[0])
    cells = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces=[]
    for r in range(h-1):
      for c in range(w-1):
        sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if sq <= cells: pieces.append((sq,1,0))
        for missing,color in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
          shape=sq-{missing}
          if shape <= cells: pieces.append((shape,color,1))
    # exact cover using minimal number of pieces; square preferred
    bycell={p:set() for p in cells}
    for i,(shape,_,_) in enumerate(pieces):
      for x in shape: bycell[x].add(i)
    best=None
    def search(rem,chosen):
      nonlocal best
      if not rem:
        score=(len(chosen),sum(pieces[i][2] for i in chosen))
        if best is None or score<best[0]: best=(score,chosen[:])
        return
      if best and len(chosen)>=best[0][0]: return
      x=min(rem,key=lambda q:sum(pieces[i][0]<=rem for i in bycell[q]))
      for i in bycell[x]:
        shape=pieces[i][0]
        if shape<=rem: search(rem-shape,chosen+[i])
    search(cells,[])
    out=[[0]*w for _ in range(h)]
    if best:
      for i in best[1]:
        shape,color,_=pieces[i]
        for r,c in shape: out[r][c]=color
    return out
